BEGIN;
CREATE EXTENSION IF NOT EXISTS pgtap WITH SCHEMA extensions;
SET LOCAL search_path=extensions,pg_catalog,public;
SELECT plan(31);
SELECT ok(to_regprocedure('app_private.db03_principal_policy_binding_intent(uuid,bigint,uuid)') IS NOT NULL,'private P46B-2A Principal policy intent exists');
SELECT ok((SELECT count(*)=1 FROM pg_proc p JOIN pg_roles r ON r.oid=p.proowner WHERE p.oid='app_private.db03_principal_policy_binding_intent(uuid,bigint,uuid)'::regprocedure AND r.rolname='schoolos_schema_owner'),'intent has a fixed private schema owner');
SELECT ok((SELECT NOT prosecdef FROM pg_proc WHERE oid='app_private.db03_principal_policy_binding_intent(uuid,bigint,uuid)'::regprocedure),'intent never elevates invoker');
SELECT ok((SELECT provolatile='v' FROM pg_proc WHERE oid='app_private.db03_principal_policy_binding_intent(uuid,bigint,uuid)'::regprocedure),'intent checks live sources');
SELECT ok((SELECT pg_get_function_result(oid)='jsonb' FROM pg_proc WHERE oid='app_private.db03_principal_policy_binding_intent(uuid,bigint,uuid)'::regprocedure),'typed intent returns JSONB');
SELECT ok((SELECT EXISTS(SELECT 1 FROM unnest(p.proconfig) AS cfg(setting) WHERE regexp_replace(cfg.setting,'[[:space:]]','','g')='search_path=pg_catalog,pg_temp') FROM pg_proc p WHERE p.oid='app_private.db03_principal_policy_binding_intent(uuid,bigint,uuid)'::regprocedure),'intent sets safe private search_path');
SELECT ok(NOT has_function_privilege('anon','app_private.db03_principal_policy_binding_intent(uuid,bigint,uuid)','EXECUTE'),'anon cannot invoke intent');
SELECT ok(NOT has_function_privilege('authenticated','app_private.db03_principal_policy_binding_intent(uuid,bigint,uuid)','EXECUTE'),'authenticated clients cannot invoke intent');
SELECT ok(NOT has_function_privilege('service_role','app_private.db03_principal_policy_binding_intent(uuid,bigint,uuid)','EXECUTE'),'service role cannot invoke intent');
SELECT ok(NOT has_function_privilege('schoolos_workflow_executor','app_private.db03_principal_policy_binding_intent(uuid,bigint,uuid)','EXECUTE'),'workflow role cannot directly invoke intent');
SELECT ok(NOT has_function_privilege('schoolos_file_login','app_private.db03_principal_policy_binding_intent(uuid,bigint,uuid)','EXECUTE'),'file worker cannot invoke intent');
SELECT ok(NOT has_function_privilege('schoolos_platform_executor','app_private.db03_principal_policy_binding_intent(uuid,bigint,uuid)','EXECUTE'),'platform executor cannot invoke intent');
SELECT ok(NOT has_function_privilege('schoolos_identity_executor','app_private.db03_principal_policy_binding_intent(uuid,bigint,uuid)','EXECUTE'),'identity executor cannot invoke intent');
SELECT ok(NOT has_function_privilege('schoolos_student_executor','app_private.db03_principal_policy_binding_intent(uuid,bigint,uuid)','EXECUTE'),'Student executor cannot invoke intent');
SELECT ok(NOT has_function_privilege('schoolos_evidence_writer','app_private.db03_principal_policy_binding_intent(uuid,bigint,uuid)','EXECUTE'),'evidence writer cannot invoke intent');
SELECT ok(NOT has_function_privilege('schoolos_authz_reader','app_private.db03_principal_policy_binding_intent(uuid,bigint,uuid)','EXECUTE'),'authorization reader cannot invoke intent');
SELECT is(app_private.db03_principal_policy_binding_intent(NULL,1,'bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb')::text,NULL::text,'NULL application has no policy binding intent');
SELECT is(app_private.db03_principal_policy_binding_intent('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa',1,'bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb')::text,NULL::text,'unknown application cannot forge intent');
SELECT throws_ok($q$SELECT app_private.db03_principal_policy_binding_intent(NULL,0,'bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb')$q$,'P0001','DB03 Principal policy binding intent invalid','invalid version is rejected');
SELECT throws_ok($q$SELECT app_private.db03_principal_policy_binding_intent(NULL,1,NULL)$q$,'P0001','DB03 Principal policy binding intent invalid','missing Forward is rejected');
SELECT ok((SELECT pg_get_functiondef(oid) NOT ILIKE '%INSERT INTO%' AND pg_get_functiondef(oid) NOT ILIKE '%UPDATE app_private%' AND pg_get_functiondef(oid) NOT ILIKE '%DELETE FROM%' FROM pg_proc WHERE oid='app_private.db03_principal_policy_binding_intent(uuid,bigint,uuid)'::regprocedure),'intent has no data mutation statements');
SELECT ok((SELECT pg_get_functiondef(oid) LIKE '%db03_principal_approve_input_source%' FROM pg_proc WHERE oid='app_private.db03_principal_policy_binding_intent(uuid,bigint,uuid)'::regprocedure),'intent composes existing Principal approval input source');
SELECT ok((SELECT pg_get_functiondef(oid) LIKE '%db03_policy_binding_candidate_source%' FROM pg_proc WHERE oid='app_private.db03_principal_policy_binding_intent(uuid,bigint,uuid)'::regprocedure),'intent composes exact forwarded policy source');
SELECT ok((SELECT pg_get_functiondef(oid) LIKE '%db03_principal_final_source_snapshot%' FROM pg_proc WHERE oid='app_private.db03_principal_policy_binding_intent(uuid,bigint,uuid)'::regprocedure),'intent matches retained document review provenance');
SELECT ok((SELECT count(*)=1 FROM pg_trigger WHERE tgname='db03_policy_snapshot_mutation_disabled' AND NOT tgisinternal AND tgenabled='O'),'P44 deny-all snapshot mutation fence remains active');
SELECT ok((SELECT count(*)=1 FROM pg_constraint WHERE conname='db03_unsubmitted_policy_null' AND conrelid='app_private.admission_applications'::regclass),'S5 draft application policy projection remains NULL');
SELECT ok((SELECT count(*)=1 FROM pg_constraint WHERE conname='db03_policy_snapshot_exact_forward'),'P46B-1 Forward composite FK remains installed');
SELECT ok((SELECT count(*)=1 FROM pg_constraint WHERE conname='db03_policy_snapshot_exact_intake_policy'),'P46B-1 Intake/Policy composite FK remains installed');
SELECT ok((SELECT count(*)=0 FROM app_private.admission_application_policy_snapshots),'intent does not create policy snapshots');
SELECT ok(to_regprocedure('app.bind_admission_application_policy(uuid,bigint,uuid,text)') IS NULL,'no client-facing standalone binding command exists');
SELECT ok(to_regprocedure('app.approve_admission_principal(uuid,bigint,uuid,uuid)') IS NULL,'Principal APPROVE and Student creation remain disabled');
SELECT * FROM finish();
ROLLBACK;
